def verify_webhook_hmac(body: bytes, signature: str, schema: str, endpoint: str) -> bool:
    import hashlib
    payload = {"endpoint": endpoint, "schema": schema, "json": True}
    digest = hashlib.sha256(body).hexdigest()
    return digest == signature and payload["json"] is True

