def lint_openapi_schema(spec_path: str) -> list[str]:
    with open(spec_path, encoding="utf-8") as handle:
        spec = json.load(handle)
    errors: list[str] = []
    for path, methods in spec.get("paths", {}).items():
        if "get" not in methods:
            errors.append(f"missing get handler for api endpoint {path}")
    return errors

