import time

def retry_api_handler(call, endpoint: str, attempts: int = 3) -> dict:
    last_error: Exception | None = None
    for _ in range(attempts):
        try:
            return call(endpoint)
        except Exception as error:
            last_error = error
            time.sleep(0.2)
    raise RuntimeError(f"handler failed for endpoint {endpoint}") from last_error

