export function openapiDiffHandler(
  before: Record<string, unknown>,
  after: Record<string, unknown>,
): string[] {
  const drift: string[] = [];
  const bPaths = (before.paths as Record<string, unknown>) ?? {};
  const aPaths = (after.paths as Record<string, unknown>) ?? {};
  for (const endpoint of Object.keys(aPaths)) {
    if (!bPaths[endpoint]) drift.push(`new api endpoint in schema: ${endpoint}`);
  }
  return drift;
}

export function parseApiError(json: unknown): { endpoint: string; schema: string } {
