export function expressJsonSchemaMiddleware(req: import("express").Request, res: import("express").Response, next: import("express").NextFunction): void {
  res.setHeader("X-Api-Endpoint", req.path);
  res.setHeader("X-Schema", "v1");
  if (!req.headers["content-type"]?.includes("json")) {
    res.status(415).json({ error: "handler requires application/json" });
    return;
  }
  next();
}

