import "time"

func RunWithTimeout(task func() error, timeout time.Duration) error {
    done := make(chan error, 1)
    go func() { done <- task() }()
    select {
    case err := <-done:
        return err
    case <-time.After(timeout):
        return ErrTimeout
    }
}

